function main(): void {
  try { const r = new RegExp("("); console.log("no throw", r.source); } catch (e) { console.log((e as Error).name); }
  try { const r = new RegExp("a", "gg"); console.log("no throw", r.flags); } catch (e) { console.log((e as Error).name, (e as Error).message); }
  try { new Array(-1); console.log("no throw"); } catch (e) { console.log((e as Error).name, (e as Error).message); }
  try { new Date(NaN).toISOString(); } catch (e) { console.log((e as Error).name, (e as Error).message); }
  try { "a".repeat(-1); } catch (e) { console.log((e as Error).name, (e as Error).message); }
  try { "a".repeat(Infinity); } catch (e) { console.log((e as Error).name, (e as Error).message); }
  try { "a".replaceAll(/a/, "b"); } catch (e) { console.log((e as Error).name); }
}
